package theme

import (
	"math"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

// A load gauge: a bar that answers "is something hot" without reading a
// number (§3.71).
//
// It renders plain text and nothing else. Rule 122 is why: a gradient along
// the bar — green cells then orange ones inside the same cell — would need
// ANSI sequences inside what Cell returns, runewidth counts those as width,
// and the cut lands mid-sequence and bleeds over every row below. So the
// length carries the value, and LoadTextStyle gives the whole cell one colour.

// The fill glyphs, pinned by measurement rather than by taste.
//
// Every glyph in the Block Elements range — `█`, `▓`, `▇`, and the partial
// blocks `▏▎▍▌` — is East Asian *ambiguous*: runewidth measures it 1 here and
// 2 under an East Asian locale, so a terminal that renders it double-width
// makes the row overflow its column and breaks Rule 116. Measured, not
// assumed: `▓` and `▉` come back ambiguous, `░` does not.
//
// Braille is the one family that measures 1 in both conditions, and it is
// already the alphabet the dashboard draws its curves in — so the gauge is in
// the same visual family as the charts rather than in one of its own.
const (
	gaugeFull  = "⣿" // eight dots: a whole cell
	gaugeHalf  = "⡇" // the left column of dots: half a cell
	gaugeEmpty = "░" // the track, and the only non-braille glyph — it measures 1 in both conditions too
)

// GaugeWidth is the width of a gauge column, in cells.
//
// Six, which buys twelve steps at half-cell resolution — enough to tell a
// quarter from a third at a glance, which is all a bar is for. The number it
// sits beside carries the precision.
const GaugeWidth = 6

// Load thresholds, in percent. Below the first, a gauge takes the ordinary
// text colour.
//
// Rule 122 decides these rather than taste: the nominal, majority state gets
// no colour of its own, and most containers idle near zero. A bar coloured on
// every row would put a colour on the whole table and a signal on none of it —
// which is also why nothing here is ever green.
const (
	// LoadWarnPercent is where a gauge stops being ordinary: filling up, and
	// worth noticing.
	LoadWarnPercent = 75
	// LoadCriticalPercent is where it is nearly full — the memory gauge's
	// reading of a container about to meet its limit.
	LoadCriticalPercent = 90
)

// Gauge renders pct of full as a bar of width cells, as plain text.
//
// pct is clamped: anything at or above 100 fills the bar. Saturation is
// therefore indistinguishable from exactly full, which is deliberate and is
// the reason a gauge never replaces the number beside it — `docker stats`
// counts CPU against one core, so two busy cores read 200% and only the
// number tells the two apart (§3.71).
//
// Rounding is honest in the other direction too: a container at 0.1% renders
// an empty track rather than a token sliver. Half a cell out of six *is* 8%,
// so drawing one for a value near zero would overstate it on every idle row —
// and idle is what most rows are.
func Gauge(pct float64, width int) string {
	if width <= 0 {
		return ""
	}
	switch {
	case math.IsNaN(pct), pct < 0:
		pct = 0
	case pct > 100:
		pct = 100
	}

	halves := int(math.Round(pct / 100 * float64(width*2)))
	full, half := halves/2, halves%2

	var b strings.Builder
	b.WriteString(strings.Repeat(gaugeFull, full))
	if half > 0 {
		b.WriteString(gaugeHalf)
		full++
	}
	b.WriteString(strings.Repeat(gaugeEmpty, width-full))
	return b.String()
}

// LoadTextStyle is the colour a gauge takes at pct: ordinary text, then
// orange, then red. It follows SeverityTextStyle's shape — the view names a
// value, the theme answers with a colour — and it aliases the severity palette
// for the same reason the footer levels do (Rule 128): one alphabet across the
// application, so a full gauge reads like a CRITICAL finding.
//
// It is a function rather than a package-level style because the thresholds
// are the whole of it; a var per level would leave the switch in the view,
// which is where Rule 125 says a colour must not be decided.
func LoadTextStyle(pct float64) lipgloss.Style {
	base := lipgloss.NewStyle().Background(ColorBackground)
	switch {
	case pct >= LoadCriticalPercent:
		return base.Foreground(ColorSeverityCritical).Bold(true)
	case pct >= LoadWarnPercent:
		return base.Foreground(ColorSeverityMedium)
	default:
		return base.Foreground(ColorText)
	}
}

package theme

import (
	"strings"
	"testing"

	"github.com/mattn/go-runewidth"
)

// A gauge is measured by datatable before it is coloured, so its rendered
// width has to be exactly what the column declared — at every value, and under
// an East Asian locale as much as under this one. That is the whole reason the
// fill glyphs are braille rather than block elements.
func TestAGaugeIsExactlyAsWideAsItAsksFor(t *testing.T) {
	eastAsian := &runewidth.Condition{EastAsianWidth: true}

	for _, width := range []int{1, 2, 6, 20} {
		for pct := -50.0; pct <= 150.0; pct += 0.5 {
			bar := Gauge(pct, width)
			if got := runewidth.StringWidth(bar); got != width {
				t.Fatalf("Gauge(%.1f, %d) measures %d cells, want %d: %q", pct, width, got, width, bar)
			}
			if got := eastAsian.StringWidth(bar); got != width {
				t.Fatalf("Gauge(%.1f, %d) measures %d cells under an East Asian locale, want %d: %q",
					pct, width, got, width, bar)
			}
		}
	}
}

func TestGaugeFillsInProportion(t *testing.T) {
	tests := []struct {
		name string
		pct  float64
		want string
	}{
		// An idle container renders an empty track, not a token sliver: half a
		// cell out of six is 8%, and drawing one for 0.1% would overstate it on
		// every row of a table where idle is the majority state.
		{"zero", 0, "░░░░░░"},
		{"idle", 0.4, "░░░░░░"},
		{"a quarter", 25, "⣿⡇░░░░"},
		{"a half", 50, "⣿⣿⣿░░░"},
		{"three quarters", 75, "⣿⣿⣿⣿⡇░"},
		{"full", 100, "⣿⣿⣿⣿⣿⣿"},
		// Saturation is indistinguishable from full — the number beside the
		// gauge is what tells 200% from 100%.
		{"two busy cores", 200, "⣿⣿⣿⣿⣿⣿"},
		// A negative or unreadable value is not a full bar.
		{"negative", -10, "░░░░░░"},
	}

	for _, tc := range tests {
		if got := Gauge(tc.pct, GaugeWidth); got != tc.want {
			t.Errorf("%s: Gauge(%v, %d) = %q, want %q", tc.name, tc.pct, GaugeWidth, got, tc.want)
		}
	}
}

// A width of zero renders nothing rather than panicking on a negative repeat
// count: a column narrow enough to have been dropped still calls Cell during
// measurement.
func TestGaugeSurvivesAnEmptyWidth(t *testing.T) {
	for _, width := range []int{0, -1} {
		if got := Gauge(50, width); got != "" {
			t.Errorf("Gauge(50, %d) = %q, want the empty string", width, got)
		}
	}
}

// Rule 122's colour discipline: the majority state carries no colour of its
// own, and nothing here is ever green.
func TestOnlyALoadedGaugeIsColoured(t *testing.T) {
	tests := []struct {
		pct  float64
		want string
	}{
		{0, string(ColorText)},
		{LoadWarnPercent - 0.1, string(ColorText)},
		{LoadWarnPercent, string(ColorSeverityMedium)},
		{LoadCriticalPercent - 0.1, string(ColorSeverityMedium)},
		{LoadCriticalPercent, string(ColorSeverityCritical)},
		{400, string(ColorSeverityCritical)},
	}

	for _, tc := range tests {
		if got := LoadTextStyle(tc.pct).GetForeground(); string(got.(interface{ String() string }).String()) != tc.want {
			t.Errorf("LoadTextStyle(%v) foreground = %v, want %v", tc.pct, got, tc.want)
		}
	}
}

// The gauge glyphs are pinned here rather than in a comment: swapping one for a
// block element would pass every other test in this file and overflow the
// column on a terminal nobody in this repository runs.
func TestTheFillGlyphsAreNotAmbiguousWidth(t *testing.T) {
	for _, glyph := range []string{gaugeFull, gaugeHalf, gaugeEmpty} {
		for _, r := range glyph {
			if runewidth.IsAmbiguousWidth(r) {
				t.Errorf("gauge glyph %q (U+%04X) is East Asian ambiguous: it renders double-width on some terminals and breaks Rule 116", string(r), r)
			}
		}
	}
	if strings.ContainsAny(gaugeFull+gaugeHalf+gaugeEmpty, "█▓▒▉▊▋▌▍▎▏▁▂▃▄▅▆▇") {
		t.Error("a Block Elements glyph is back in the gauge; every one of them is ambiguous-width")
	}
}

